import { useCallback, useMemo, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

import { FilterRegistry } from 'domain/Filter';
import { FilterForm, FilterValue } from 'models/Filters';
import { scrollToTop } from 'utils/scroll';

import { usePageFilterApplied, usePageFilterData } from '../useFilters/core';

export type RelatedAnalysisOrigin = 'brand-power' | 'performance-tool';

export interface RelatedAnalysisRouteState {
  fromRelatedAnalysis: true;
  origin: RelatedAnalysisOrigin;
}

const RELATED_ANALYSIS_CONTEXT_STORAGE_KEY = 'related-analysis-context';

interface UseRelatedAnalysisNavigationParams {
  sourcePageName: string;
  destinationPath: string;
  origin: RelatedAnalysisOrigin;
  fixedFilters?: Partial<FilterForm>;
  preserveCountry?: boolean;
  preserveZoneWithCountry?: boolean;
  warningIgnoreKeys?: string[];
}

const hasFilterValue = (value: unknown): value is string | number =>
  value !== null && value !== undefined && value !== '';

const normalizeFilterValue = (value: FilterValue | undefined) =>
  typeof value === 'string' || typeof value === 'number' ? String(value) : '';

export const isRelatedAnalysisRouteState = (
  state: unknown,
): state is RelatedAnalysisRouteState => {
  if (!state || typeof state !== 'object') return false;

  const candidate = state as Record<string, unknown>;
  const hasExpectedOrigin =
    candidate.origin === 'brand-power' ||
    candidate.origin === 'performance-tool';

  return candidate.fromRelatedAnalysis === true && hasExpectedOrigin;
};

const readStoredRelatedAnalysisOrigin = (): RelatedAnalysisOrigin | null => {
  const storedOrigin = sessionStorage.getItem(
    RELATED_ANALYSIS_CONTEXT_STORAGE_KEY,
  );

  if (storedOrigin === 'brand-power' || storedOrigin === 'performance-tool') {
    return storedOrigin;
  }

  return null;
};

const persistRelatedAnalysisOrigin = (origin: RelatedAnalysisOrigin) => {
  sessionStorage.setItem(RELATED_ANALYSIS_CONTEXT_STORAGE_KEY, origin);
};

const clearStoredRelatedAnalysisOrigin = () => {
  sessionStorage.removeItem(RELATED_ANALYSIS_CONTEXT_STORAGE_KEY);
};

export const useRelatedAnalysisContextBanner = (
  expectedOrigin: RelatedAnalysisOrigin,
) => {
  const location = useLocation();

  const [shouldShowBanner] = useState(() => {
    if (isRelatedAnalysisRouteState(location.state)) {
      clearStoredRelatedAnalysisOrigin();
      return location.state.origin === expectedOrigin;
    }

    const storedOrigin = readStoredRelatedAnalysisOrigin();

    if (storedOrigin !== null) {
      clearStoredRelatedAnalysisOrigin();
      return storedOrigin === expectedOrigin;
    }

    return false;
  });

  return shouldShowBanner;
};

export const useRelatedAnalysisNavigation = ({
  sourcePageName,
  destinationPath,
  origin,
  fixedFilters = {},
  preserveCountry = true,
  preserveZoneWithCountry = true,
  warningIgnoreKeys = [],
}: UseRelatedAnalysisNavigationParams) => {
  const navigate = useNavigate();
  const { applied } = usePageFilterApplied(sourcePageName);
  const { defaults } = usePageFilterData(sourcePageName);

  const preservedFilters = useMemo(() => {
    const filters: Record<string, string> = {};

    Object.entries(fixedFilters).forEach(([key, value]) => {
      if (!hasFilterValue(value)) return;

      filters[key] = String(value);
    });

    if (preserveZoneWithCountry && hasFilterValue(applied.zone)) {
      filters.zone = String(applied.zone);
    }

    if (preserveCountry && hasFilterValue(applied.country)) {
      filters.country = String(applied.country);
    }

    return filters;
  }, [
    applied.country,
    applied.zone,
    fixedFilters,
    preserveCountry,
    preserveZoneWithCountry,
  ]);

  const destinationPathWithFilters = useMemo(() => {
    const sourceSearch =
      FilterRegistry.buildFilterQueryString(preservedFilters);

    return FilterRegistry.mergeFilterParamsIntoHref(
      destinationPath,
      sourceSearch,
    );
  }, [destinationPath, preservedFilters]);

  const shouldShowFilterWarning = useMemo(() => {
    const ignoredKeys = new Set([
      ...Object.keys(preservedFilters),
      ...warningIgnoreKeys,
    ]);

    if (!defaults || Object.keys(defaults).length === 0) return false;

    return Object.entries(applied).some(([key, value]) => {
      if (ignoredKeys.has(key)) return false;
      if (!hasFilterValue(value)) return false;

      const defaultValue = defaults[key];

      return normalizeFilterValue(value) !== normalizeFilterValue(defaultValue);
    });
  }, [applied, defaults, preservedFilters, warningIgnoreKeys]);

  const navigateToRelatedAnalysis = useCallback(() => {
    persistRelatedAnalysisOrigin(origin);

    navigate(destinationPathWithFilters, {
      state: {
        fromRelatedAnalysis: true,
        origin,
      } satisfies RelatedAnalysisRouteState,
    });

    scrollToTop();
  }, [destinationPathWithFilters, navigate, origin]);

  return {
    destinationPathWithFilters,
    navigateToRelatedAnalysis,
    shouldShowFilterWarning,
  };
};
